import{_ as d,o as e,c as o,a2 as a}from"./chunks/framework.XctAhZuT.js";const u=JSON.parse('{"title":"交互题型","description":"Interaction 是课程运行时的最小可执行单元。渲染器分发不直接比较 runtimeType——freezed 生成的是私有实现类（如 $ShowWordImpl），必须先经 handlesTypeFor() 映射到公开接口类型再匹配…","frontmatter":{"description":"Interaction 是课程运行时的最小可执行单元。渲染器分发不直接比较 runtimeType——freezed 生成的是私有实现类（如 $ShowWordImpl），必须先经 handlesTypeFor() 映射到公开接口类型再匹配…"},"headers":[],"relativePath":"guide/interaction-types.md","filePath":"guide/interaction-types.md","lastUpdated":1790697640000}'),r={name:"guide/interaction-types.md"};function c(i,t,n,l,s,h){return e(),o("div",null,[...t[0]||(t[0]=[a(`<h1 id="交互题型" tabindex="-1">交互题型 <a class="header-anchor" href="#交互题型" aria-label="Permalink to &quot;交互题型&quot;">​</a></h1><p>Interaction 是课程运行时的最小可执行单元。渲染器分发不直接比较 <code>runtimeType</code>——freezed 生成的是私有实现类（如 <code>_$ShowWordImpl</code>），必须先经 <code>_handlesTypeFor()</code> 映射到公开接口类型再匹配。写新渲染器时在 <code>di/renderer_module.dart</code> 登记即可，无需改分发逻辑。</p><h2 id="已定义类型" tabindex="-1">已定义类型 <a class="header-anchor" href="#已定义类型" aria-label="Permalink to &quot;已定义类型&quot;">​</a></h2><table tabindex="0"><thead><tr><th>能力维度</th><th><code>runtimeType</code></th><th>输入</th><th>结果</th></tr></thead><tbody><tr><td>词汇呈现</td><td><code>showWord</code></td><td>词项、释义、音频</td><td>展示完成</td></tr><tr><td>接受性词汇</td><td><code>multipleChoice</code></td><td>单个答案</td><td>正误</td></tr><tr><td>接受性词汇</td><td><code>multiSelect</code></td><td>多个答案</td><td>集合匹配结果</td></tr><tr><td>产出</td><td><code>fillBlank</code></td><td>文本</td><td>标准化后匹配</td></tr><tr><td>产出</td><td><code>translateSentence</code></td><td>翻译文本</td><td>规则或配置判定</td></tr><tr><td>句法</td><td><code>reorderSentence</code></td><td>词块顺序</td><td>顺序匹配</td></tr><tr><td>听写</td><td><code>typeTheWord</code></td><td>听到的词</td><td>拼写匹配</td></tr><tr><td>听力</td><td><code>listenAndPick</code></td><td>音频后的选择</td><td>正误</td></tr><tr><td>听力</td><td><code>listenOnly</code></td><td>音频</td><td>播放完成</td></tr><tr><td>阅读</td><td><code>readingMcq</code></td><td>篇章后的选择</td><td>正误</td></tr><tr><td>阅读</td><td><code>readingTrueFalse</code></td><td>真 / 假</td><td>正误</td></tr><tr><td>阅读</td><td><code>readingShortAnswer</code></td><td>简答</td><td>配置判定</td></tr><tr><td>Anki 翻卡</td><td><code>ankiCard</code></td><td>原卡正面 / 背面文本</td><td>翻面 + 课程结果</td></tr><tr><td>Anki 保真</td><td><code>ankiHtmlCard</code></td><td>原卡 HTML</td><td>见下方说明</td></tr></tbody></table><p>共 14 种（<code>lib/domain/course/interaction.dart</code> 的 sealed union，<code>tool/gui/src/backend/schema_constants.py</code> 保持一致）。</p><p>两个 Anki 题型的区别：</p><ul><li><strong><code>ankiCard</code></strong>：导入卡片的普通翻卡形态（正面 → 点按 → 背面），用于课时体与 Official 复习投影的纯文本卡。</li><li><strong><code>ankiHtmlCard</code></strong>：携带 <code>frontHtml</code> / <code>backHtml</code> / <code>allowJs</code> / <code>mediaBasePath</code> 的保真卡。Official 复习路径用 WebView 按原模板渲染；<strong>课时体与错题回放里该类型的渲染器已退役</strong>（<code>AnkiHtmlCardRetiredRenderer</code>），显示为「确认后继续」占位卡 —— 新课程不要再产出 <code>ankiHtmlCard</code> 课时项。</li></ul><h2 id="设计规则" tabindex="-1">设计规则 <a class="header-anchor" href="#设计规则" aria-label="Permalink to &quot;设计规则&quot;">​</a></h2><h3 id="先呈现-后检索" tabindex="-1">先呈现，后检索 <a class="header-anchor" href="#先呈现-后检索" aria-label="Permalink to &quot;先呈现，后检索&quot;">​</a></h3><p>新词首次出现时先使用 <code>showWord</code> 或具有明确上下文的输入。不得在没有任何输入的情况下把陌生项目直接作为高强度产出题。</p><h3 id="每题只验证一个主要目标" tabindex="-1">每题只验证一个主要目标 <a class="header-anchor" href="#每题只验证一个主要目标" aria-label="Permalink to &quot;每题只验证一个主要目标&quot;">​</a></h3><p>题干可以包含上下文，但评分目标必须明确。例如听力题验证语音识别时，不同时要求复杂拼写和语法变形，除非课时目标明确要求组合能力。</p><h3 id="干扰项必须可解释" tabindex="-1">干扰项必须可解释 <a class="header-anchor" href="#干扰项必须可解释" aria-label="Permalink to &quot;干扰项必须可解释&quot;">​</a></h3><p>选择题干扰项应来自真实易混项、相近形式或当前课程范围。随机无关词会提高表面难度，但不提供有效诊断。</p><h3 id="标识符保持稳定" tabindex="-1">标识符保持稳定 <a class="header-anchor" href="#标识符保持稳定" aria-label="Permalink to &quot;标识符保持稳定&quot;">​</a></h3><p>Interaction <code>id</code> 用于定位、错误记录和测试。发布后不得因排序调整自动重编号。</p><h2 id="评分映射" tabindex="-1">评分映射 <a class="header-anchor" href="#评分映射" aria-label="Permalink to &quot;评分映射&quot;">​</a></h2><p>普通课程题通常使用二元结果：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>pass -&gt; Good</span></span>
<span class="line"><span>fail -&gt; Again</span></span></code></pre></div><p>显式量表可以映射为四档评分。Anki 正式复习直接使用 Again、Hard、Good、Easy。显示文本可以本地化，调度枚举不可重新定义。</p><h2 id="内容检查" tabindex="-1">内容检查 <a class="header-anchor" href="#内容检查" aria-label="Permalink to &quot;内容检查&quot;">​</a></h2><p>前四项由工具强制，<code>course_cli.py</code> 会报错：</p><ul><li><code>id</code> 在目标作用域内唯一且稳定。</li><li>引用的 <code>wordId</code>、<code>expressionId</code>、<code>grammarPointId</code> 存在。</li><li>音频题的 <code>audioAsset</code> 只出现在听力课中。</li><li><code>stages</code> 与 <code>questions</code> 不同时声明。</li></ul><p>以下几项<strong>工具不校验</strong>，需人工把关：</p><ul><li><code>runtimeType</code> 是否已注册——未知类型不会报错，只会在运行时降级为占位 <code>showWord</code>。</li><li>选择题答案下标 <code>correctIndex</code> / <code>correctIndices</code> 是否落在 <code>options</code> 范围内。</li><li>空字符串、重复选项与无解题目。</li><li>音频能否真正播放（<code>audioAsset</code> 缺失只产生 warning，且其路径解析与磁盘布局不一致）。</li></ul><h2 id="相关文档" tabindex="-1">相关文档 <a class="header-anchor" href="#相关文档" aria-label="Permalink to &quot;相关文档&quot;">​</a></h2><ul><li><a href="/docs/authoring/lesson-schema">Lesson JSON 结构</a></li><li><a href="/docs/guide/lesson-types">课型说明</a></li><li><a href="/docs/authoring/validation">校验与 Lint</a></li></ul>`,27)])])}const m=d(r,[["render",c]]);export{u as __pageData,m as default};
